INSERT INTO products (product_id, title, description, material, type, base_price, photo) VALUES
 (1, 'Нож «Таёжный»', 'Охотничий нож ручной ковки из дамасской стали. Рукоять — карельская берёза, кожаные ножны в комплекте. Длина клинка 15 см.', 'Дамасская сталь', 'Нож', 8500, 'data:image/svg+xml;base64,'),
 (2, 'Топор «Северный»', 'Кованый топор для колки и плотницких работ. Закалка лезвия, топорище из ясеня, пропитка маслом.', 'Углеродистая сталь', 'Топор', 6200, 'data:image/svg+xml;base64,'),
 (3, 'Подкова на счастье', 'Сувенирная подкова с гравировкой имени или даты. Покрытие — воск с патиной.', 'Сталь', 'Сувенир', 1200, 'data:image/svg+xml;base64,'),
 (4, 'Подсвечник «Лоза»', 'Настольный подсвечник на две свечи с коваными виноградными листьями. Высота 32 см.', 'Чёрный металл', 'Декор интерьера', 3400, 'data:image/svg+xml;base64,'),
 (5, 'Каминный набор «Очаг»', 'Кочерга, совок, щётка и щипцы на кованой подставке. Термостойкая порошковая краска.', 'Сталь с патиной', 'Каминные принадлежности', 12500, 'data:image/svg+xml;base64,'),
 (6, 'Кованая роза', 'Роза из стали ручной работы — подарок, который не завянет. Длина 45 см.', 'Сталь', 'Сувенир', 1800, 'data:image/svg+xml;base64,'),
 (7, 'Мангал «Дружина»', 'Разборный мангал на 10 шампуров с крышей и полкой для дров. Толщина стенок 4 мм.', 'Листовая сталь 4 мм', 'Мангал', 28000, 'data:image/svg+xml;base64,'),
 (8, 'Перила «Виноград»', 'Кованые перила для лестниц и балконов, цена за погонный метр. Изготовление по размерам заказчика.', 'Чёрный металл', 'Ограждение', 9500, 'data:image/svg+xml;base64,'),
 (9, 'Ключница «Дом»', 'Настенная ключница с пятью крючками в форме домика. Крепёж в комплекте.', 'Сталь', 'Декор интерьера', 2600, 'data:image/svg+xml;base64,'),
 (10, 'Набор шампуров «Охотник»', 'Шесть шампуров длиной 60 см с витыми ручками и колчаном из кожи.', 'Нержавеющая сталь', 'Аксессуары для мангала', 2900, 'data:image/svg+xml;base64,'),
 (11, 'Скамья садовая «Усадьба»', 'Садовая скамья с коваными боковинами и сиденьем из морёного дуба. Длина 150 см.', 'Сталь и дуб', 'Садовая мебель', 21000, 'data:image/svg+xml;base64,'),
 (12, 'Флюгер «Кот»', 'Флюгер для крыши с силуэтом кота и розой ветров. Подшипниковый узел вращения.', 'Листовая сталь', 'Декор экстерьера', 5400, 'data:image/svg+xml;base64,');
